package com.hbm.client.missile.launchpad.large;
import com.hbm.client.particle.LegacyCoolingTowerParticle;import com.hbm.entity.missile.EntityMissileBaseNT;import com.hbm.item.missile.MissileItem.MissileFormFactor;import com.hbm.missile.launchpad.large.LargeLaunchPadBlockEntity;import com.hbm.missile.launchpad.standard.StandardLaunchPadBlockEntity;import com.hbm.multiblock.DummyableBlock;import com.hbm.registry.HbmSounds;import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.resources.sounds.AbstractTickableSoundInstance;import net.minecraft.sounds.SoundSource;import net.minecraft.util.RandomSource;import net.minecraft.world.phys.AABB;
/** Original wgh/garage dynamic loops and oxygen vapor/ground-level launchSmoke. */
public final class LargeLaunchPadEffects{private static final Map<LargeLaunchPadBlockEntity,State> STATES=new WeakHashMap<>();private static final class State{Loop lift,erector;}public static void tick(LargeLaunchPadBlockEntity pad){if(!(pad.getLevel() instanceof ClientLevel level))return;var state=STATES.computeIfAbsent(pad,p->new State());state.lift=loop(pad,state.lift,pad.liftMoving,"door.wgh_start",.75F);state.erector=loop(pad,state.erector,pad.erectorMoving,"door.garage_move",1.5F);var p=pad.getBlockPos();if(pad.erected&&(pad.formFactor==MissileFormFactor.HUGE.ordinal()||pad.formFactor==MissileFormFactor.ATLAS.ordinal())&&pad.tanks[1].getFill()>0){int life=70+level.random.nextInt(30);double x=p.getX()+.5+level.random.nextGaussian()*.5,z=p.getZ()+.5+level.random.nextGaussian()*.5;for(int i=0;i<3;i++){var particle=new LegacyCoolingTowerParticle(level,x,p.getY()+2,z);particle.setLift(0);particle.setBaseScale(.5F);particle.setMaxScale(2);particle.setLife(life);particle.noWind();particle.alphaMod(2);particle.setStrafe(.05F);Minecraft.getInstance().particleEngine.add(particle);}}if(!level.getEntitiesOfClass(EntityMissileBaseNT.class,new AABB(p.getX()-.5,p.getY(),p.getZ()-.5,p.getX()+1.5,p.getY()+10,p.getZ()+1.5)).isEmpty())for(int i=0;i<15;i++){var dir=DummyableBlock.facing(pad.getBlockState());if(level.random.nextBoolean())dir=dir.getOpposite();float mx=(float)(level.random.nextGaussian()*.15F+.75)*dir.getStepX(),mz=(float)(level.random.nextGaussian()*.15F+.75)*dir.getStepZ();StandardLaunchPadBlockEntity.smoke.accept(new StandardLaunchPadBlockEntity.Smoke(level,p.getX()+.5,p.getY()+.25,p.getZ()+.5,mx,0,mz));}}
 private static Loop loop(LargeLaunchPadBlockEntity pad,Loop loop,boolean active,String name,float volume){var mc=Minecraft.getInstance();if(active){if(loop==null||!mc.getSoundManager().isActive(loop)){loop=new Loop(pad,name,volume);mc.getSoundManager().play(loop);}loop.keepAlive=0;}else if(loop!=null){loop.finish();mc.getSoundManager().stop(loop);return null;}return loop;}public static void removed(LargeLaunchPadBlockEntity pad){var state=STATES.remove(pad);if(state!=null)for(var loop:new Loop[]{state.lift,state.erector})if(loop!=null){loop.finish();Minecraft.getInstance().getSoundManager().stop(loop);}}
 private static final class Loop extends AbstractTickableSoundInstance{final LargeLaunchPadBlockEntity pad;final float base;int keepAlive;Loop(LargeLaunchPadBlockEntity pad,String name,float base){super(HbmSounds.get(name),SoundSource.BLOCKS,RandomSource.create());this.pad=pad;this.base=base;x=pad.getBlockPos().getX();y=pad.getBlockPos().getY();z=pad.getBlockPos().getZ();looping=true;delay=0;pitch=1;attenuation=Attenuation.NONE;update();}private void update(){var player=Minecraft.getInstance().player;volume=player==null?0:base*(float)(1-Math.sqrt(player.distanceToSqr(x,y,z))/25);}@Override public void tick(){if(pad.isRemoved()||++keepAlive>5)stop();else update();}void finish(){stop();}}private LargeLaunchPadEffects(){}}
